// Floxac — ملف واحد: الخادم + التطبيق. التشغيل: node floxac.js  |  اختياري: ANTHROPIC_API_KEY لردود بوتات بذكاء اصطناعي حقيقي، TURN_URL/TURN_USER/TURN_PASS للمكالمات خلف شبكات مقيدة  (PORT env optional)
const http=require("http"),fs=require("fs"),path=require("path"),cr=require("crypto");
const F=path.join(__dirname,"data.json"),K=["rc","posts","cm","lk","fw","sv","st","dm","nt","rp"];
const OW={rc:"u",posts:"uid",cm:"uid",lk:"u",fw:"a",sv:"u",st:"uid",dm:"a",nt:"from",rp:"u"};
let db={users:{},tokens:{}};K.forEach(k=>db[k]=[]);
try{db=Object.assign(db,JSON.parse(fs.readFileSync(F,"utf8")))}catch(e){}K.forEach(k=>db[k]=db[k]||[]);
let st=0;const save=()=>{clearTimeout(st);st=setTimeout(()=>fs.writeFile(F+".tmp",JSON.stringify(db),e=>!e&&fs.rename(F+".tmp",F,()=>{})),400)};
const ASSETS={};[["/index.html","text/html",""],["/icon.svg","image/svg+xml",""],["/manifest.webmanifest","application/manifest+json",""],["/sw.js","text/javascript",""]].forEach(([p,m,d])=>ASSETS[p]=[Buffer.from(d,"base64"),m]);
const FL=new Map(),rid=()=>Date.now().toString(36)+cr.randomBytes(3).toString("hex"),hash=(p,s)=>cr.scryptSync(p,s,32).toString("hex");
const COL=["#0F6B4F","#C9A227","#1B6A8A","#9A4A2A","#6B3FA0","#B23A6B"],MIME={".html":"text/html",".js":"text/javascript",".svg":"image/svg+xml",".webmanifest":"application/manifest+json"};
const clients=new Map(),push=(u,ev,d)=>(clients.get(u)||[]).forEach(r=>r.write(`event: ${ev}\ndata: ${JSON.stringify(d||0)}\n\n`)),pingAll=()=>clients.forEach((_,u)=>push(u,"ch"));
const pub=u=>{const{ph,salt,...r}=u;return r},who=t=>db.tokens[t];
/* bots */
const B=[["nour","Nour Al-Din","شاعر وكاتب. أحب الحروف والقهوة."],["layla","Layla Hart","Photographer chasing golden hour."],["omar","Omar Sky","مطوّر ومحب للتقنية 🚀"],["sara_dev","Sara Dev","Frontend dev • coffee • cats ☕"],["yazan","Yazan Fit","مدرب لياقة. خطوة كل يوم 💪"],["mia.travels","Mia Travels","Collecting sunsets 🌍"]];
B.forEach(([id,n,bio],i)=>{if(!db.users[id])db.users[id]={id,user:id,name:n,bio,color:COL[i%6],bot:1}});
const T=["صباح الخير ☀️ #صباح","خطوة صغيرة اليوم أفضل من خطة كبيرة غدًا #تحفيز","Golden hour hits different today. #light","Coffee first, then conquer ☕ #coffee","Consistency beats intensity. #growth","غروب اليوم كان خياليًا 🌇 #تصوير"],C=["رائع! 👏","Love this ✨","جميل جدًا","Great one 🔥","شكرًا للمشاركة ❤️"],R=["هلا! كيف حالك؟ 😊","Tell me more!","ههه حلو، وأنت؟","Thanks, that's kind ❤️","Sounds good 🙌"],pk=a=>a[Math.random()*a.length|0];
const KEY=process.env.ANTHROPIC_API_KEY,persona=u=>"You are "+u.name+", "+u.bio+" You are a real-sounding person on a social app. Write casually and briefly (max 2 short sentences), in the same language as the text you are given (Arabic or English). Output only the message, no quotes or explanations.";
async function ai(sys,usr,fb){if(!KEY)return fb;try{const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"content-type":"application/json","x-api-key":KEY,"anthropic-version":"2023-06-01"},body:JSON.stringify({model:process.env.AI_MODEL||"claude-haiku-5-5",max_tokens:150,system:sys,messages:[{role:"user",content:usr}]}),signal:AbortSignal.timeout(15000)});const j=await r.json();return(j.content&&j.content[0]&&j.content[0].text||"").trim()||fb}catch(e){return fb}}
const hum=()=>Object.values(db.users).filter(u=>!u.bot);
setInterval(async()=>{const b=pk(B)[0],r=Math.random(),H=hum();if(r<.3)db.posts.push({id:rid(),uid:b,body:await ai(persona(db.users[b]),"Write one new social media post (under 140 characters) in "+pk(["Arabic","English"])+".",pk(T)),ts:Date.now()});else if(r<.4)db.st.push({id:rid(),uid:b,text:pk(T).replace(/#\S+/g,"").trim(),bg:Math.random()*6|0,ts:Date.now()});
else if(r<.7){const p=pk(db.posts.filter(p=>p.uid!==b&&!p.rp));if(p&&!db.lk.some(k=>k.p===p.id&&k.u===b)){db.lk.push({p:p.id,u:b});}}
else if(r<.85){const p=pk(db.posts.filter(p=>!p.rp&&!db.users[p.uid]?.bot));if(p){db.cm.push({id:rid(),pid:p.id,uid:b,text:await ai(persona(db.users[b]),"Write a short friendly comment on this post: "+p.body,pk(C)),ts:Date.now()});db.nt.push({id:rid(),to:p.uid,type:"c",from:b,pid:p.id,ts:Date.now(),read:0})}}
else if(H.length){const u=pk(H).id;if(!db.fw.some(f=>f.a===b&&f.b===u)){db.fw.push({a:b,b:u});db.nt.push({id:rid(),to:u,type:"f",from:b,ts:Date.now(),read:0})}}save();pingAll()},30000);
/* http */
const body=q=>new Promise(r=>{let s="";q.on("data",c=>{s+=c;if(s.length>6e7)q.destroy()});q.on("end",()=>{try{r(JSON.parse(s||"{}"))}catch(e){r({})}})});
const J=(res,c,o)=>{res.writeHead(c,{"Content-Type":"application/json"});res.end(JSON.stringify(o))};
http.createServer(async(q,res)=>{const u=new URL(q.url,"http://x"),p=u.pathname;
if(p==="/api/ping")return J(res,200,{ok:1});
if(p==="/api/ice"){const i=[{urls:"stun:stun.l.google.com:19302"},{urls:"stun:stun1.l.google.com:19302"}];i.push({urls:"turn:openrelay.metered.ca:80",username:"openrelayproject",credential:"openrelayproject"},{urls:"turn:openrelay.metered.ca:443?transport=tcp",username:"openrelayproject",credential:"openrelayproject"});if(process.env.TURN_URL)i.push({urls:process.env.TURN_URL,username:process.env.TURN_USER,credential:process.env.TURN_PASS});return J(res,200,i)}
if(p==="/api/stream"){const me=who(u.searchParams.get("t"));if(!me)return J(res,401,{});res.writeHead(200,{"Content-Type":"text/event-stream","Cache-Control":"no-cache",Connection:"keep-alive"});res.write("retry: 3000\n\n");clients.set(me,[...(clients.get(me)||[]),res]);const hb=setInterval(()=>res.write(": hb\n\n"),20000);q.on("close",()=>{clearInterval(hb);clients.set(me,(clients.get(me)||[]).filter(x=>x!==res))});return}
if(q.method==="POST"&&p.startsWith("/api/")){const b=await body(q);
if(p==="/api/signup"){const id=String(b.u||"").trim().toLowerCase();if(!/^[a-z0-9_.]{3,20}$/.test(id)||String(b.p||"").length<6||!b.n)return J(res,400,{e:"inv"});if(db.users[id])return J(res,409,{e:"taken"});const salt=rid();db.users[id]={id,user:id,name:String(b.n).slice(0,30),bio:"",color:COL[Math.floor(Math.random()*6)],salt,ph:hash(b.p,salt)};const t=cr.randomBytes(24).toString("hex");db.tokens[t]=id;save();return J(res,200,{t,id})}
if(p==="/api/login"){const ip=q.socket.remoteAddress,z=FL.get(ip)||{n:0,ts:Date.now()};if(Date.now()-z.ts>6e5){z.n=0;z.ts=Date.now()}if(z.n>=10)return J(res,429,{e:"bad"});const x=db.users[String(b.u||"").trim().toLowerCase()];if(!x||x.bot||x.ph!==hash(String(b.p||""),x.salt)){z.n++;FL.set(ip,z);return J(res,401,{e:"bad"})}FL.delete(ip);const t=cr.randomBytes(24).toString("hex");db.tokens[t]=x.id;save();return J(res,200,{t,id:x.id})}
const me=who(b.t);if(!me)return J(res,401,{e:"auth"});
if(p==="/api/sig"){push(b.to,"sig",{from:me,msg:b.msg});return J(res,200,{})}
if(p==="/api/sync"){const own=b.own||{};if(b.prof&&db.users[me]){const x=db.users[me];["name","bio","color","av"].forEach(k=>{if(b.prof[k]!=null)x[k]=b.prof[k]})}
let ch=0;K.forEach(k=>{if(!own[k])return;const o=OW[k],old=new Map(db[k].filter(x=>x[o]===me).map(x=>[x.id||x.p+x.u+x.a+x.b,x])),nw=own[k].filter(x=>x[o]===me);nw.forEach(x=>{const o2=old.get(x.id||x.p+x.u+x.a+x.b);if(o2&&o2.m&&!x.m)x.m=o2.m});db[k]=db[k].filter(x=>x[o]!==me).concat(nw);ch=1});
if(b.delacc&&db.users[me]){delete db.users[me];Object.keys(db.tokens).forEach(t=>db.tokens[t]===me&&delete db.tokens[t]);K.forEach(k=>db[k]=db[k].filter(x=>x[OW[k]]!==me));ch=1}
// bot replies to new DMs
nwDM:for(const d of db.dm.filter(d=>d.a===me&&db.users[d.b]?.bot&&!d.bz)){d.bz=1;(async()=>{const bt=db.users[d.b],h=db.dm.filter(x=>(x.a===me&&x.b===d.b)||(x.a===d.b&&x.b===me)).slice(-8).map(x=>(x.a===me?"User: ":bt.name+": ")+(x.v?"[voice message]":x.t)).join("\n"),t=await ai(persona(bt),h+"\n"+bt.name+":",pk(R));setTimeout(()=>{db.dm.push({id:rid(),a:d.b,b:me,t,ts:Date.now(),r:0});save();push(me,"ch")},1200+Math.random()*1800)})()}
if(ch){save();pingAll()}
const have=new Set(b.have||[]),out={users:Object.fromEntries(Object.entries(db.users).map(([k,v])=>[k,pub(v)]))};
K.forEach(k=>{out[k]=db[k].filter(x=>x[OW[k]]!==me&&(k!=="dm"||x.b===me)&&(k!=="nt"||x.to===me)).map(x=>x.m&&have.has(x.id)?{...x,m:0,keep:1}:x)});
return J(res,200,out)}}
const a=ASSETS[p==="/"?"/index.html":p];if(!a){res.writeHead(404);return res.end("404")}
res.writeHead(200,{"Content-Type":a[1]+"; charset=utf-8","Cache-Control":"no-cache"});res.end(a[0])}).listen(process.env.PORT||8080,()=>console.log("Floxac on http://localhost:"+(process.env.PORT||8080)));
